/** Read-only, source-scoped adviser queries. No tracking, publishing or external calls. */
import {err,known,manager,one,rows,source,pagination,exact,CURRENCIES,day} from './common.mjs';
import {operationFilters,localMidnight,shiftDay,nativeWhere} from './analytics.mjs';
