const ALL_METRICS=[...ADVISER_METRICS,...DERIVED_METRICS],PAID="('paid','fulfilled','partially_refunded','refunded')";
const NATIVE=`SELECT 'leads' entity,public_id,name,company,email,country,product_interest product,status,source_page,locale,utm_source,utm_medium,utm_campaign,'' industry,created_at,updated_at FROM leads UNION ALL SELECT 'rfqs',public_id,name,company,email,country,COALESCE(NULLIF(product_model,''),product_category),status,source_page,locale,utm_source,utm_medium,utm_campaign,industry,created_at,updated_at FROM rfqs UNION ALL SELECT 'support',public_id,name,company,email,'' country,product_model,status,source_page,locale,utm_source,utm_medium,utm_campaign,'' industry,created_at,updated_at FROM support_requests UNION ALL SELECT 'downloads',public_id,name,company,email,country,COALESCE(NULLIF(product_model,''),requested_file),status,source_page,locale,utm_source,utm_medium,utm_campaign,'' industry,created_at,updated_at FROM download_requests`;
const EVENT_KEYS={product_views:'product.viewed',cart_additions:'cart.added',quote_requests:'quote.requested'};
const QUERY_KEYS=['view','from','to','source_id','currency','country','product','sku','keyword','channel','device','industry','locale','event_type','compare','metrics','page','limit','metric','bucket_from','bucket_to','q','exclude_tests','group_by','status','fulfillment_status','owner_id','series','profile_email'];
